INSERT INTO `hw_details_agent_ia` VALUES (1,1,'HW WhatsApp Agent',NULL,'hw-whatsapp-agent','Agent conversationnel WhatsApp 24/7','Un agent IA qui répond, qualifie et relance vos prospects sur WhatsApp 24/7 : devis, prise de RDV et routage vers le bon service, connecté à votre CRM.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">HW WhatsApp Agent <em>— Agent conversationnel WhatsApp 24/7</em></h2>\n    <p class=\"aic-quote-src rv\">Automatisez la relation client, la qualification et les relances WhatsApp avec un agent IA connecté à votre CRM.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Vos prospects <em>n\'attendent<br>pas le lundi.</em></h2>\n        <p class=\"aic-lead rv\">Trop de messages WhatsApp sans réponse la nuit, trop de prospects perdus le week-end, trop d\'allers-retours commerciaux pour des devis répétitifs.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Messages sans réponse la nuit</h3>\n            <p class=\"aic-pain-body\">Un prospect qui écrit à 22h et n\'a pas de réponse avant le lendemain matin part généralement voir un concurrent.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Prospects perdus le week-end</h3>\n            <p class=\"aic-pain-body\">Les demandes du samedi et du dimanche s\'accumulent sans qualification, ralentissant tout le pipeline commercial du lundi.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Devis répétitifs chronophages</h3>\n            <p class=\"aic-pain-body\">Vos commerciaux répondent aux mêmes questions de budget et de délai des dizaines de fois par semaine, sans valeur ajoutée.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un agent qui <em>répond, qualifie<br>et planifie</em> pour vous.</h2>\n        <p class=\"aic-lead rv\">HW WhatsApp Agent répond instantanément, qualifie le besoin, propose un budget, prend rendez-vous sur Google Calendar et confirme par email. Bilingue FR/EN, routage intelligent vers commercial, marketing, RH ou support.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-comment-dots\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">HW WhatsApp Agent</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">ASTRO</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonjour ! Je suis ASTRO. Vous cherchez un devis, un RDV ou un service précis ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Un devis pour un site e-commerce.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Parfait. Budget indicatif : 25 000 à 60 000 MAD selon les fonctionnalités. Je vous propose un créneau avec notre équipe ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Oui, demain si possible.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>RDV confirmé demain à 15h — invitation Google Calendar envoyée ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"HW WhatsApp Agent\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Réponse instantanée 24/7</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Qualification automatique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Bilingue FR / EN</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Routage intelligent</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Estimation budgétaire instantanée</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Prise de RDV Google Calendar</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">7</span>\n          <span class=\"aic-split-list-text\">Confirmation multicanale</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Immobilier</strong>Campagnes sortantes et qualification automatique des acheteurs et locataires intéressés par une annonce.</li>\n        <li><strong>Restaurant</strong>Prise de commande directe sur WhatsApp, avec confirmation immédiate et rappel du ticket au client.</li>\n        <li><strong>E-commerce</strong>Service après-vente et qualification des prospects avant transfert vers l\'équipe commerciale dédiée.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">&lt;30<span>s</span></div>\n        <div class=\"aic-kpi-ttl\">Réponse garantie</div>\n        <p class=\"aic-kpi-body\">Chaque message WhatsApp reçoit une première réponse en moins de 30 secondes, 24 heures sur 24.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-filter\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de qualification</div>\n        <p class=\"aic-kpi-body\">Chaque conversation est scorée et enrichie automatiquement avant transfert à votre équipe commerciale.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-redo\"></i></div>\n        <div class=\"aic-kpi-ttl\">Efficacité des relances</div>\n        <p class=\"aic-kpi-body\">Les prospects silencieux sont relancés automatiquement selon un calendrier configurable, sans effort manuel.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. HW WhatsApp Agent s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"HW WhatsApp Agent\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp Business API</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#2ED573\"><i class=\"fal fa-chart-line\"></i>Pipedrive</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#E42527\"><i class=\"fal fa-database\"></i>Zoho</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#4285F4\"><i class=\"fal fa-calendar-alt\"></i>Google Calendar</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#00897B\"><i class=\"fal fa-video\"></i>Meet</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#2D8CFF\"><i class=\"fal fa-video\"></i>Zoom</div>\n        <div class=\"aic-orbit-item pos-8 rv\" style=\"--tool-color:#6264A7\"><i class=\"fab fa-microsoft\"></i>Teams</div>\n      </div>\n    </div>\n  </div>\n</section>','HW WhatsApp Agent — Agent WhatsApp IA | Hello World Agency','Automatisez relation, qualification et relances WhatsApp avec un agent IA connecté à votre CRM. Bilingue FR/EN, routage intelligent, RDV Google Calendar.','fr'),(2,2,'HW Content Studio',NULL,'hw-content-studio','Créez et partagez des visuels en automatique','Vos nouveaux contenus détectés et partagés automatiquement sur tous vos réseaux, avec une accroche adaptée à chaque plateforme et au meilleur créneau.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">HW Content Studio <em>— Créez et partagez des visuels en automatique</em></h2>\n    <p class=\"aic-quote-src rv\">Vos nouveaux contenus partagés automatiquement sur tous vos réseaux — avec l\'accroche adaptée.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Un article publié, <em>quatre<br>réseaux oubliés.</em></h2>\n        <p class=\"aic-lead rv\">Vous publiez un article et vous oubliez de le partager sur 4 plateformes. Vos posts sont irréguliers et l\'algorithme vous pénalise.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Partage oublié après publication</h3>\n            <p class=\"aic-pain-body\">Un contenu publié sur le site ne trouve jamais son chemin vers les réseaux sociaux faute de temps ou de suivi.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Régularité impossible à tenir</h3>\n            <p class=\"aic-pain-body\">Sans planning automatisé, les publications s\'espacent de façon aléatoire et l\'algorithme réduit votre portée.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Accroche identique sur tous les réseaux</h3>\n            <p class=\"aic-pain-body\">Un même message copié-collé partout ne performe nulle part : chaque plateforme a ses codes et ses formats.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Détecte, adapte <em>et publie</em><br>à votre place.</h2>\n        <p class=\"aic-lead rv\">HW Content Studio détecte chaque nouvelle URL sur votre CMS ou sitemap, rédige une accroche adaptée à chaque réseau et programme la diffusion au meilleur créneau.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-share-alt\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">HW Content Studio</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">ORBIT</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Nouvel article détecté : « Guide SEO Maroc 2026 ». Je prépare les publications.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Sur quels réseaux ?</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>LinkedIn, Instagram et Facebook. Accroche adaptée à chaque format, créneau optimal à 18h.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Parfait, valide.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Publications programmées ✓ — rapport de performance envoyé demain matin.</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"HW Content Studio\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Détection automatique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Accroche par réseau</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Créneau optimal</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Synchronisation visuelle</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Analytics par plateforme</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Recommandation best time to post</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Blog média</strong>12 partages générés automatiquement par article, sans aucune intervention de l\'équipe éditoriale.</li>\n        <li><strong>Site e-commerce</strong>Chaque nouvelle fiche produit est diffusée automatiquement sur les réseaux au moment de sa mise en ligne.</li>\n        <li><strong>Agence multi-comptes</strong>Gère la diffusion en marque blanche pour plusieurs clients depuis un seul tableau de bord centralisé.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">+55<span>%</span></div>\n        <div class=\"aic-kpi-ttl\">Trafic social référent</div>\n        <p class=\"aic-kpi-body\">La régularité et la couverture multi-réseaux augmentent significativement le trafic issu du social.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">-95<span>%</span></div>\n        <div class=\"aic-kpi-ttl\">Temps de partage</div>\n        <p class=\"aic-kpi-body\">Le temps consacré manuellement à la diffusion social media est quasiment ramené à zéro.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-calendar-check\"></i></div>\n        <div class=\"aic-kpi-ttl\">Régularité de publication</div>\n        <p class=\"aic-kpi-body\">Un rythme de diffusion constant, sans dépendre de la disponibilité d\'un community manager.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. HW Content Studio s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"HW Content Studio\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#21759B\"><i class=\"fab fa-wordpress\"></i>WordPress</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#4353FF\"><i class=\"fal fa-code\"></i>Webflow</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#168EEA\"><i class=\"fal fa-share-alt\"></i>Buffer</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#143059\"><i class=\"fal fa-share-square\"></i>Hootsuite</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#0866FF\"><i class=\"fab fa-facebook\"></i>Meta Business Suite</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#0A66C2\"><i class=\"fab fa-linkedin\"></i>LinkedIn</div>\n      </div>\n    </div>\n  </div>\n</section>','HW Content Studio — Partage social automatisé IA | Hello World Agency','Agent IA de partage social : détection des nouveaux contenus, accroche par réseau, meilleur créneau, synchronisation image/vidéo et analytics par plateforme.','fr'),(3,3,'Booking Assistant',NULL,'booking-assistant','Gestion intelligente des rendez-vous','Vos agendas synchronisés, vos rendez-vous confirmés automatiquement et vos no-shows réduits de moitié grâce à un agent intelligent disponible 24/7.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Booking Assistant <em>— Gestion intelligente des rendez-vous</em></h2>\n    <p class=\"aic-quote-src rv\">Synchronisez vos agendas, confirmez automatiquement et réduisez les no-shows de moitié avec un agent intelligent.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Un rendez-vous manqué,<br><em>un revenu perdu.</em></h2>\n        <p class=\"aic-lead rv\">Les rendez-vous manqués coûtent cher. Les confirmations email passent inaperçues. Google et Outlook ne se parlent pas entre eux.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">No-shows coûteux et fréquents</h3>\n            <p class=\"aic-pain-body\">Chaque rendez-vous manqué représente un créneau perdu qui aurait pu être occupé par un autre client.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Confirmations email ignorées</h3>\n            <p class=\"aic-pain-body\">Les rappels par email se perdent dans la boîte de réception et n\'atteignent jamais leur objectif de rétention.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Agendas non synchronisés</h3>\n            <p class=\"aic-pain-body\">Google Calendar et Outlook fonctionnent en silos, provoquant des doublons de réservation et des erreurs de planning.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un agenda qui se <em>remplit<br>tout seul</em>, sans erreur.</h2>\n        <p class=\"aic-lead rv\">Booking Assistant détecte les créneaux libres sur vos agendas, propose une réservation en self-service, envoie confirmations email et SMS, alerte à J-1 et H-2, et replanifie automatiquement en cas d\'empêchement.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-calendar-check\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Booking Assistant</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">LYRA</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonjour, je suis LYRA. Je vous trouve un créneau disponible cette semaine ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Oui, plutôt en fin de journée.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Jeudi 17h ou vendredi 17h30, lequel préférez-vous ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Jeudi 17h.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>RDV confirmé jeudi à 17h — SMS de rappel prévu la veille ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Booking Assistant\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Synchronisation multi-agenda</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Page de réservation branded</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Buffer intelligent</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Confirmation email + SMS</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Rappel J-1 et H-2</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Replanification self-service</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">7</span>\n          <span class=\"aic-split-list-text\">Mode file d\'attente</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Santé & Cliniques</strong>Prise de rendez-vous patient avec rappels automatiques pour réduire les absences en consultation.</li>\n        <li><strong>Conseil & Cabinets</strong>Gestion des rendez-vous clients pour avocats, comptables et consultants indépendants.</li>\n        <li><strong>Showrooms & Concessions</strong>Organisation des rendez-vous d\'essai et de présentation produit sans double réservation.</li>\n        <li><strong>Formateurs & Coaching</strong>Planification automatique des sessions visio avec rappel systématique avant chaque rendez-vous.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">-50<span>%</span></div>\n        <div class=\"aic-kpi-ttl\">Réduction des no-shows</div>\n        <p class=\"aic-kpi-body\">Objectif atteint grâce à la double confirmation et aux rappels automatiques programmés.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-sms\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de confirmation SMS</div>\n        <p class=\"aic-kpi-body\">La majorité des rendez-vous sont confirmés activement par le client avant le jour J.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-moon\"></i></div>\n        <div class=\"aic-kpi-ttl\">RDV pris hors heures ouvrées</div>\n        <p class=\"aic-kpi-body\">Le self-service permet aux clients de réserver le soir ou le week-end, sans attendre l\'ouverture.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Booking Assistant s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Booking Assistant\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#4285F4\"><i class=\"fal fa-calendar-alt\"></i>Google Calendar</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#0078D4\"><i class=\"fal fa-envelope\"></i>Outlook</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#006BFF\"><i class=\"fal fa-calendar-check\"></i>Calendly</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#635BFF\"><i class=\"fab fa-stripe\"></i>Stripe</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#F22F46\"><i class=\"fal fa-sms\"></i>Twilio SMS</div>\n      </div>\n    </div>\n  </div>\n</section>','Booking Assistant — Prise de RDV IA | Hello World Agency','Synchronisation Google/Outlook, réservation en self-service, confirmations SMS, rappels J-1 et replanification automatique. No-show divisés par deux.','fr'),(4,4,'Resto Assistant',NULL,'resto-assistant','Service client IA pour la restauration','Le serveur digital de votre restaurant : réservations, commandes à emporter et questions menu traitées 24/7, en français, arabe et anglais.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Resto Assistant <em>— Service client IA pour la restauration</em></h2>\n    <p class=\"aic-quote-src rv\">Le serveur digital pour votre restaurant : réservations, commandes et questions menu traitées 24/7.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Le téléphone sonne,<br><em>personne ne répond.</em></h2>\n        <p class=\"aic-lead rv\">Téléphone saturé pendant le service. Serveurs submergés. Commandes WhatsApp noyées dans les messages personnels et professionnels.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Téléphone saturé en service</h3>\n            <p class=\"aic-pain-body\">Impossible de répondre aux appels de réservation pendant le coup de feu, au détriment du service en salle.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Serveurs surchargés</h3>\n            <p class=\"aic-pain-body\">Le personnel jongle entre les tables et les appels, ralentissant l\'expérience de tous les clients présents.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Commandes WhatsApp perdues</h3>\n            <p class=\"aic-pain-body\">Les commandes à emporter se mélangent avec les messages personnels et finissent oubliées ou en retard.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un serveur digital <em>toujours<br>disponible</em>, jamais débordé.</h2>\n        <p class=\"aic-lead rv\">Resto Assistant prend les réservations, gère les commandes à emporter, répond aux questions menu (allergènes, ruptures, suggestions) et envoie les confirmations cuisine. Multi-langue FR/AR/EN.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-utensils\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Resto Assistant</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">EMBER</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonsoir ! Je suis EMBER. Réservation, commande ou question sur le menu ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Une table pour 4 personnes ce soir.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>20h ou 20h30, quelle heure vous convient le mieux ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>20h30.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Table pour 4 à 20h30 confirmée ✓ À ce soir !</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Resto Assistant\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Menu dynamique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Multi-langue FR / AR / EN</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Upsell automatique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">NPS post-visite</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Invitation avis Google</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Notification cuisine</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Restaurants toutes tailles</strong>De la brasserie de quartier à la chaîne multi-établissements, un accueil constant et fiable.</li>\n        <li><strong>Cafés & Snacking</strong>Gestion des commandes à emporter aux heures de pointe sans perdre un seul client impatient.</li>\n        <li><strong>Traiteurs événementiels</strong>Prise de commandes groupées et suivi des demandes spécifiques pour chaque événement.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-calendar-day\"></i></div>\n        <div class=\"aic-kpi-ttl\">Réservations automatiques / jour</div>\n        <p class=\"aic-kpi-body\">Un flux constant de réservations traitées sans mobiliser le personnel en salle.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-smile-beam\"></i></div>\n        <div class=\"aic-kpi-ttl\">NPS post-visite</div>\n        <p class=\"aic-kpi-body\">Un suivi systématique de la satisfaction, exploitable pour ajuster le service en continu.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-star-half-alt\"></i></div>\n        <div class=\"aic-kpi-ttl\">Avis Google générés</div>\n        <p class=\"aic-kpi-body\">Une croissance régulière des avis positifs grâce aux sollicitations automatiques post-visite.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Resto Assistant s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Resto Assistant\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#0B87F5\"><i class=\"fal fa-bolt\"></i>Lightspeed</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#3E4348\"><i class=\"fal fa-credit-card\"></i>Square</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#FF5A00\"><i class=\"fal fa-truck\"></i>Deliverect</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#00AA4F\"><i class=\"fal fa-utensils\"></i>TheFork</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp Business</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#4285F4\"><i class=\"fal fa-star\"></i>Google Avis</div>\n      </div>\n    </div>\n  </div>\n</section>','Resto Assistant — Bot restaurant IA | Hello World Agency','Agent IA restaurant WhatsApp : réservations, commandes à emporter, menu dynamique FR/AR/EN, intégration Lightspeed/Square/Deliverect, avis Google.','fr'),(5,5,'HW Concierge AI',NULL,'hw-concierge-ai','Réceptionniste virtuelle sur WhatsApp','<p>Votre accueil disponible 24/7 sur WhatsApp. Notre agent joue le r&ocirc;le de r&eacute;ceptionniste : orientation, prise d&#39;information, transfert vers le bon interlocuteur.</p>\r\n','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">HW Concierge AI <em>— Relation client premium</em></h2>\n    <p class=\"aic-quote-src rv\">Un concierge IA premium qui guide, répond, recommande et convertit vos clients 24/7 sur tous vos canaux digitaux — une présence humaine et disponible, du premier contact à la fidélisation.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Vos clients premium<br>n\'ont pas <em>le temps<br>d\'attendre.</em></h2>\n        <p class=\"aic-lead rv\">Vos clients premium exigent une réponse immédiate et personnalisée. Votre équipe support sature et perd des opportunités d\'upsell faute de temps pour bien suivre chaque dossier.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Temps de réponse trop long</h3>\n            <p class=\"aic-pain-body\">Les attentes dépassent 5 minutes. Vos clients partent vers la concurrence, insatisfaits avant même d\'avoir été aidés.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Équipe support surchargée</h3>\n            <p class=\"aic-pain-body\">Votre personnel gère trop de demandes répétitives à faible valeur ajoutée, au détriment de la relation client premium.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Opportunités d\'upsell perdues</h3>\n            <p class=\"aic-pain-body\">Sans suivi personnalisé, chaque interaction manquée représente des revenus non réalisés et une fidélité fragilisée.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un agent qui répond <em>en expert</em>,<br>jamais en robot.</h2>\n        <p class=\"aic-lead rv\">HW Concierge AI est l\'agent conversationnel haut de gamme conçu pour les marques de luxe, l\'hôtellerie et les services clients premium. Alimenté par RAG, il interroge votre base de connaissances, vos catalogues et votre CRM pour fournir une réponse experte en langage naturel — jamais robotique.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-robot\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">HW Concierge AI</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">BOARDY</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonjour ! Je suis BOARDY, votre concierge IA. Comment puis-je vous aider ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Bonjour, j\'ai besoin d\'un late checkout.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Votre late checkout jusqu\'à 14h est confirmé. Souhaitez-vous autre chose pour votre départ ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Une table au restaurant ce soir pour 2.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Table pour 2 à 20h à La Terrasse — confirmée ✓ Un SMS de rappel vous sera envoyé à 19h.</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"HW Concierge AI\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-database\"></i></span>\n          <span class=\"aic-split-list-text\">Réponses RAG issues de votre base de connaissance</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-tags\"></i></span>\n          <span class=\"aic-split-list-text\">Recommandations produit contextuelles</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-level-up-alt\"></i></span>\n          <span class=\"aic-split-list-text\">Upsell intelligent selon profil client</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-language\"></i></span>\n          <span class=\"aic-split-list-text\">Multilingue FR / AR / EN</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-headset\"></i></span>\n          <span class=\"aic-split-list-text\">Transfert vers humain avec contexte conservé</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-user-circle\"></i></span>\n          <span class=\"aic-split-list-text\">Profil client enrichi en temps réel</span>\n        </li>\n\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-hotel\"></i></span>\n          <span><strong>Hôtellerie</strong>Conciergerie digitale 24/7 — check-in/out, réservations restaurant, recommandations locales et upsell de suite.</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-gem\"></i></span>\n          <span><strong>Luxe & Retail premium</strong>Assistant boutique en ligne — conseil produit personnalisé, vérification disponibilité, tunnel d\'achat guidé.</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-stethoscope\"></i></span>\n          <span><strong>Cliniques privées</strong>Accueil et onboarding patient — prise de rendez-vous, FAQ médicale, rappels et suivi post-consultation.</span>\n        </li>\n\n        <li>\n          <span class=\"aic-split-use-ico\"><i class=\"fal fa-landmark\"></i></span>\n          <span><strong>Banque privée</strong>Premier niveau relation client — informations compte, orientation services, prise de RDV conseiller dédié.</span>\n        </li>\n\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">&lt;2<span>s</span></div>\n        <div class=\"aic-kpi-ttl\">Réponse contextuelle</div>\n        <p class=\"aic-kpi-body\">Temps de réponse garanti quelle que soit la complexité de la demande client.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-chart-line\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux d\'upsell mesurable</div>\n        <p class=\"aic-kpi-body\">Chaque opportunité tracée et reportée dans votre dashboard en temps réel.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">24<span>/7</span></div>\n        <div class=\"aic-kpi-ttl\">Disponibilité totale</div>\n        <p class=\"aic-kpi-body\">Site web, WhatsApp Business, email, chat — présence unifiée sans aucune interruption.</p>\n      </div>\n    </div>\n  </div>\n</section>\n<!-- ── INTÉGRATIONS — orbite 3D ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em></h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. HW Concierge AI s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"HW Concierge AI\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#00A1E0\"><i class=\"fab fa-salesforce\"></i>Salesforce</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#E42527\"><i class=\"fal fa-address-book\"></i>Zoho CRM</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp Business</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#6366F1\"><i class=\"fal fa-globe\"></i>CMS</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#7C3AED\"><i class=\"fal fa-calendar-check\"></i>Booking Engines</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#059669\"><i class=\"fal fa-hotel\"></i>PMS Hôteliers</div>\n      </div>\n    </div>\n  </div>\n</section>','Réceptionniste IA WhatsApp | HWM Intelligence Artificielle','Un réceptionniste virtuel sur WhatsApp pour accueillir, orienter et qualifier vos demandes entrantes 24h/24.','fr'),(6,6,'Content Broadcaster',NULL,'content-broadcaster','Distribution automatique de contenu','Des sujets d\'actualité identifiés, des articles SEO rédigés, illustrés et publiés automatiquement — 2 à 3 fois par semaine, sans effort éditorial.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Content Broadcaster <em>— Distribution automatique de contenu</em></h2>\n    <p class=\"aic-quote-src rv\">Des sujets d\'actualité identifiés, des articles SEO rédigés, illustrés et publiés automatiquement.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Un blog à l\'arrêt,<br><em>un SEO qui stagne.</em></h2>\n        <p class=\"aic-lead rv\">Votre blog est à l\'arrêt. La régularité éditoriale manque, les rédacteurs coûtent cher, et le SEO ne décolle pas.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Blog à l\'arrêt depuis des mois</h3>\n            <p class=\"aic-pain-body\">Sans production régulière, le référencement stagne et les concurrents captent le trafic organique.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Rédacteurs freelance coûteux</h3>\n            <p class=\"aic-pain-body\">Chaque article externalisé représente un coût récurrent difficile à maintenir sur la durée.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Sujets choisis au hasard</h3>\n            <p class=\"aic-pain-body\">Sans veille structurée, les articles publiés ne correspondent pas toujours aux requêtes réellement recherchées.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un studio éditorial <em>qui ne<br>s\'arrête jamais.</em></h2>\n        <p class=\"aic-lead rv\">Content Broadcaster est le workflow de production de contenu SEO 100% automatisé : veille d\'actualité locale, sélection de sujets, rédaction H1/H2/H3, génération d\'images, maillage interne, publication programmée.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-broadcast-tower\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Content Broadcaster</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">BROADCAST</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Veille terminée : 3 sujets à fort potentiel identifiés cette semaine.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Montre-moi le meilleur.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>« Tendances marketing digital Maroc 2026 » — volume de recherche élevé, faible concurrence.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Go, rédige-le.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Article rédigé, illustré et programmé pour publication jeudi 9h ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Content Broadcaster\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Veille d\'actualité locale</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Sélection intelligente de sujets</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Rédaction structurée Hn</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Mots-clés intégrés</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Maillage interne automatique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Images et illustrations générées</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">7</span>\n          <span class=\"aic-split-list-text\">Publication programmée</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Marketing</strong>Construction d\'un blog d\'autorité qui alimente en continu le pipeline de leads organiques.</li>\n        <li><strong>Agences SEO</strong>Production à l\'échelle pour agences et e-commerçants souhaitant industrialiser leur contenu.</li>\n        <li><strong>Immobilier</strong>Mises à jour régulières de chantiers et actualités de programmes en cours de commercialisation.</li>\n        <li><strong>Médias & Corporate</strong>Production thématique régulière pour alimenter la ligne éditoriale d\'un site institutionnel.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-tachometer-alt\"></i></div>\n        <div class=\"aic-kpi-ttl\">Vitesse de production</div>\n        <p class=\"aic-kpi-body\">Un article complet — recherche, rédaction, illustration — produit en quelques minutes.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-arrow-up\"></i></div>\n        <div class=\"aic-kpi-ttl\">Positions SEO Google</div>\n        <p class=\"aic-kpi-body\">Une régularité éditoriale qui alimente durablement le classement sur les mots-clés ciblés.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">2-3<span>/sem</span></div>\n        <div class=\"aic-kpi-ttl\">Volume d\'articles publiés</div>\n        <p class=\"aic-kpi-body\">Un rythme de publication soutenu et constant, impossible à tenir manuellement dans la durée.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Content Broadcaster s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Content Broadcaster\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#21759B\"><i class=\"fab fa-wordpress\"></i>WordPress</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#4353FF\"><i class=\"fal fa-code\"></i>Webflow</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#95BF47\"><i class=\"fab fa-shopify\"></i>Shopify</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#4285F4\"><i class=\"fal fa-search\"></i>Google Search Console</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#FF7A00\"><i class=\"fal fa-chart-bar\"></i>Ahrefs</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#FF6A2B\"><i class=\"fal fa-chart-line\"></i>SEMrush</div>\n      </div>\n    </div>\n  </div>\n</section>','Content Broadcaster — Production contenu SEO IA | Hello World Agency','Production éditoriale SEO automatisée : veille de sujets, rédaction Hn, maillage interne, images, publication WordPress/Webflow/Shopify.','fr'),(7,7,'Project Tracker',NULL,'project-tracker','Rapports chantier quotidiens automatisés','Vos acquéreurs informés chaque jour de l\'avancement de leur bien, grâce à l\'analyse automatique des photos de chantier vs planning prévisionnel.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Project Tracker <em>— Rapports chantier quotidiens automatisés</em></h2>\n    <p class=\"aic-quote-src rv\">Vos acquéreurs informés chaque jour de l\'avancement de leur bien — sans intervention humaine.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Le téléphone sonne,<br><em>« où en est mon bien ? »</em></h2>\n        <p class=\"aic-lead rv\">Les acquéreurs appellent tous les jours pour demander où en est leur bien. Les rapports coûtent cher en coordination. Les photos s\'empilent sans traitement.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Appels quotidiens de suivi</h3>\n            <p class=\"aic-pain-body\">Chaque acquéreur sollicite individuellement l\'équipe pour connaître l\'avancement, saturant les lignes.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Rapports coûteux en coordination</h3>\n            <p class=\"aic-pain-body\">Produire un rapport d\'avancement manuel mobilise du temps précieux chaque semaine sur chaque programme.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Photos de chantier non exploitées</h3>\n            <p class=\"aic-pain-body\">Des centaines de clichés s\'accumulent sans être transformés en information utile pour les acquéreurs.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Chaque photo devient <em>un<br>rapport clair.</em></h2>\n        <p class=\"aic-lead rv\">Project Tracker analyse les photos de chantier envoyées par l\'équipe terrain ou les caméras IP, en extrait l\'avancement vs planning, et envoie chaque jour un rapport court et clair aux acquéreurs via WhatsApp et email.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-hard-hat\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Project Tracker</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">ATLAS</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonjour, voici le rapport chantier du jour pour votre villa lot 12.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Merci, où en est-on sur la toiture ?</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Toiture à 80% d\'avancement, conforme au planning prévisionnel de la semaine 14.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Parfait.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Photo comparative J / J-1 disponible dans votre espace client ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Project Tracker\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Analyse photo IA</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Détection d\'écart planning</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Rapport rédigé automatiquement</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Envoi multicanal acquéreurs</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Comparaison photo J / J-1</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Tableau de bord maître d\'ouvrage</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Promoteurs immobiliers</strong>Suivi automatisé de plusieurs programmes en parallèle avec reporting acquéreur unifié.</li>\n        <li><strong>Bureaux d\'études</strong>Contrôle de conformité entre l\'avancement réel et les plans de maîtrise d\'œuvre.</li>\n        <li><strong>Villas & Résidences</strong>Suivi individualisé pour chaque acquéreur d\'un programme résidentiel en cours de construction.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-smile\"></i></div>\n        <div class=\"aic-kpi-ttl\">Satisfaction acquéreur (NPS)</div>\n        <p class=\"aic-kpi-body\">Une transparence quotidienne qui renforce durablement la confiance envers le promoteur.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-phone-slash\"></i></div>\n        <div class=\"aic-kpi-ttl\">Réduction des appels</div>\n        <p class=\"aic-kpi-body\">Le volume d\'appels de coordination diminue nettement grâce au rapport automatique quotidien.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-check-circle\"></i></div>\n        <div class=\"aic-kpi-ttl\">Respect du planning</div>\n        <p class=\"aic-kpi-body\">Une détection précoce des écarts permet une correction plus rapide de la trajectoire chantier.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Project Tracker s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Project Tracker\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#EA4335\"><i class=\"fal fa-envelope\"></i>Gmail</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#0F9D58\"><i class=\"fab fa-google-drive\"></i>Google Drive</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#000000\"><i class=\"fal fa-file-alt\"></i>Notion</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#217346\"><i class=\"fal fa-tasks\"></i>MS Project</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#6B7280\"><i class=\"fal fa-video\"></i>Caméras IP</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#4A154B\"><i class=\"fab fa-slack\"></i>Slack</div>\n      </div>\n    </div>\n  </div>\n</section>','Project Tracker — Suivi chantier IA | Hello World Agency','Agent IA suivi chantier : analyse photo vs planning, rapport journalier WhatsApp/email acquéreurs, détection d\'écart, tableau de bord maître d\'ouvrage.','fr'),(8,8,'Lead Finder',NULL,'lead-finder','Extraction intelligente de données web','Une liste B2B enrichie, scorée et segmentée automatiquement — sans jamais acheter de base froide ni enrichir un contact manuellement un par un.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Lead Finder <em>— Extraction intelligente de données web</em></h2>\n    <p class=\"aic-quote-src rv\">Liste B2B enrichie, scorée et segmentée — sans jamais acheter de base froide.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Des bases froides, <em>des<br>commerciaux dans le vide.</em></h2>\n        <p class=\"aic-lead rv\">Vous achetez des bases froides. Vous perdez du temps à enrichir un contact un par un. Vos commerciaux démarchent dans le vide.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Bases de données froides</h3>\n            <p class=\"aic-pain-body\">Les listes achetées sont rarement à jour et génèrent un taux de réponse décevant dès le premier contact.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Enrichissement manuel chronophage</h3>\n            <p class=\"aic-pain-body\">Vérifier et compléter chaque contact un par un mobilise un temps considérable pour un résultat incertain.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Prospection sans signal d\'achat</h3>\n            <p class=\"aic-pain-body\">Sans détection des bons moments, les commerciaux contactent des cibles qui ne sont simplement pas prêtes.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Des contacts <em>scorés</em>,<br>jamais froids.</h2>\n        <p class=\"aic-lead rv\">Lead Finder scrape en continu sources corporate, LinkedIn et registres Maroc, et enrichit chaque contact trouvé à partir de signaux d\'achat (recrutement, levée de fonds, ouverture) avec un scoring de fiabilité multi-critères.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-crosshairs\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Lead Finder</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">NEXUS</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Nouveau signal d\'achat détecté : levée de fonds chez une entreprise ciblée.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Montre-moi la fiche contact.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Contact décisionnaire enrichi, email vérifié, score de fiabilité 87/100.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Ajoute-le à la séquence commerciale.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Ajouté au pipeline HubSpot ✓ — premier email programmé demain 9h.</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Lead Finder\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Crawl multi-sources</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Détection de signaux d\'achat</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Email pattern guessing</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Vérification anti-rebond</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Scoring de fiabilité 0-100</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Détection direct vs indirect</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>SSII & Conseil</strong>Génération continue de listes qualifiées pour les équipes commerciales de services B2B.</li>\n        <li><strong>Agences</strong>Alimentation régulière du pipeline commercial sans dépendre d\'achats de bases externes.</li>\n        <li><strong>Courtiers & Recruteurs</strong>Identification de profils et d\'entreprises en phase de croissance ou de recrutement actif.</li>\n        <li><strong>Immobilier commercial</strong>Repérage d\'entreprises en expansion susceptibles de rechercher de nouveaux locaux.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-database\"></i></div>\n        <div class=\"aic-kpi-ttl\">Volume de leads enrichis</div>\n        <p class=\"aic-kpi-body\">Un flux constant de nouveaux contacts qualifiés alimente le pipeline commercial en continu.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-undo\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de rebond email</div>\n        <p class=\"aic-kpi-body\">La vérification systématique maintient un taux de rebond bas et protège votre réputation d\'envoi.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">0-100<span></span></div>\n        <div class=\"aic-kpi-ttl\">Score moyen de fiabilité</div>\n        <p class=\"aic-kpi-body\">Chaque contact est noté pour prioriser les efforts commerciaux sur les cibles les plus prometteuses.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Lead Finder s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Lead Finder\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#0A66C2\"><i class=\"fab fa-linkedin\"></i>LinkedIn Sales Navigator</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#2E6ADE\"><i class=\"fal fa-rocket\"></i>Apollo</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#2ED573\"><i class=\"fal fa-chart-line\"></i>Pipedrive</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#00A1E0\"><i class=\"fab fa-salesforce\"></i>Salesforce</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#EA4335\"><i class=\"fal fa-envelope\"></i>Gmail</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#0F9D58\"><i class=\"fal fa-table\"></i>Sheets</div>\n      </div>\n    </div>\n  </div>\n</section>','Lead Finder — Scraping B2B IA | Hello World Agency','Agent IA scraping B2B : sources corporate, LinkedIn, registres Maroc, signaux d\'achat, email pattern guessing, score de fiabilité de 0 à 100.','fr'),(9,9,'WhatsApp Campaign Agent',NULL,'whatsapp-campaign-agent','Campagnes WhatsApp ciblées et automatisées','Des campagnes WhatsApp marketing segmentées, A/B testées et tracées, envoyées avec des modèles approuvés Meta — sans jamais finir en spam.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">WhatsApp Campaign Agent <em>— Campagnes WhatsApp ciblées et automatisées</em></h2>\n    <p class=\"aic-quote-src rv\">Campagnes WhatsApp marketing segmentées, A/B testées et tracées — sans jamais finir en spam.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Vos campagnes <em>finissent<br>bloquées.</em></h2>\n        <p class=\"aic-lead rv\">Vos SMS marketing coûtent cher et ne sont plus lus. Vos campagnes WhatsApp se font bloquer par Meta. Vous n\'avez pas de reporting clair.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">SMS marketing coûteux et ignorés</h3>\n            <p class=\"aic-pain-body\">Le taux de lecture des SMS chute année après année, pour un coût d\'envoi qui reste élevé.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Campagnes bloquées par Meta</h3>\n            <p class=\"aic-pain-body\">Un envoi mal cadencé ou mal formulé déclenche des restrictions sur votre compte WhatsApp Business.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Absence de reporting fiable</h3>\n            <p class=\"aic-pain-body\">Impossible de savoir précisément quels messages performent sans un suivi structuré des campagnes.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Des campagnes <em>qui passent</em>,<br>jamais en spam.</h2>\n        <p class=\"aic-lead rv\">WhatsApp Campaign Agent envoie vos campagnes WhatsApp avec des modèles multi-formats approuvés Meta, A/B testing des accroches, segmentation dynamique, envoi échelonné anti-spam et dashboard live des performances.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-bullhorn\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">WhatsApp Campaign Agent</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">PULSE</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Campagne « Soldes été » prête : 2 variantes A/B configurées.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Lance sur le segment clients actifs.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Envoi échelonné démarré sur 3 200 contacts, cadence anti-spam activée.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Résultats dans 24h ?</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Dashboard en temps réel disponible dès maintenant, rapport complet demain matin ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"WhatsApp Campaign Agent\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Modèles approuvés Meta</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">A/B testing des messages</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Envoi échelonné anti-spam</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Heatmap des heures de lecture</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Segmentation dynamique</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Conformité RGPD native</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">7</span>\n          <span class=\"aic-split-list-text\">Gestion du désabonnement</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>E-commerce</strong>Relances promotionnelles et récupération des paniers abandonnés directement sur WhatsApp.</li>\n        <li><strong>Agences</strong>Gestion de campagnes clients multiples depuis un tableau de bord centralisé et sécurisé.</li>\n        <li><strong>Immobilier</strong>Relance ciblée des acquéreurs potentiels selon leur avancement dans le tunnel de vente.</li>\n        <li><strong>Écoles & Formation</strong>Relance des prospects inscrits en liste d\'attente ou en phase de décision d\'inscription.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-eye\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de lecture / réponse</div>\n        <p class=\"aic-kpi-body\">Un engagement nettement supérieur aux canaux traditionnels grâce au ciblage et au bon créneau.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-fire\"></i></div>\n        <div class=\"aic-kpi-ttl\">Heatmap engagement</div>\n        <p class=\"aic-kpi-body\">Une visibilité complète sur les moments d\'ouverture les plus performants par segment.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-shield-alt\"></i></div>\n        <div class=\"aic-kpi-ttl\">Conformité RGPD</div>\n        <p class=\"aic-kpi-body\">Chaque envoi respecte les exigences de consentement et de désabonnement en vigueur.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. WhatsApp Campaign Agent s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"WhatsApp Campaign Agent\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp Business API</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#F22F46\"><i class=\"fal fa-sms\"></i>Twilio</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#0B996E\"><i class=\"fal fa-paper-plane\"></i>Brevo</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#0F9D58\"><i class=\"fal fa-table\"></i>Sheets</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#0866FF\"><i class=\"fab fa-facebook\"></i>Meta Business Suite</div>\n      </div>\n    </div>\n  </div>\n</section>','WhatsApp Campaign Agent — Campagnes WhatsApp IA | Hello World Agency','Campagnes WhatsApp marketing segmentées, A/B testées, heatmap d\'engagement, conformité RGPD et envoi anti spam-flag natif Meta.','fr'),(10,10,'HW Voice Caller',NULL,'hw-voice-caller','Agent IA de gestion des appels','Relances téléphoniques, confirmations de rendez-vous et qualification sortante assurées par une voix IA conversationnelle en trois langues.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">HW Voice Caller <em>— Agent IA de gestion des appels</em></h2>\n    <p class=\"aic-quote-src rv\">Relances téléphoniques, confirmations de RDV et qualification sortante — par une voix IA conversationnelle.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Des appels manqués,<br><em>un QA à 1%.</em></h2>\n        <p class=\"aic-lead rv\">Vos commerciaux raccrochent à mi-parcours de leur mission outbound. Les confirmations RDV sont oubliées. Le QA n\'échantillonne que 1% des appels.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Missions outbound inachevées</h3>\n            <p class=\"aic-pain-body\">Les campagnes d\'appels sortants s\'essoufflent avant d\'avoir couvert l\'intégralité du fichier de contacts.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Confirmations de RDV oubliées</h3>\n            <p class=\"aic-pain-body\">Sans rappel systématique, une part importante des rendez-vous n\'est jamais reconfirmée à temps.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Contrôle qualité quasi inexistant</h3>\n            <p class=\"aic-pain-body\">Seul un échantillon infime des appels est réellement écouté et analysé pour en tirer des enseignements.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Une voix IA <em>qui appelle</em>,<br>rapporte, transmet.</h2>\n        <p class=\"aic-lead rv\">HW Voice Caller appelle vos contacts avec une voix multilingue naturelle FR/AR/EN, qualifie en 6 questions maximum, transcrit la conversation, renvoie un résumé IA et transmet le tout dans votre CRM avec un tag.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-phone-volume\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">HW Voice Caller</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">VOX</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Bonjour, je suis VOX, l\'assistant vocal de Hello World. Vous avez deux minutes ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Oui, je vous écoute.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Je confirme votre rendez-vous de jeudi à 14h. Cela vous convient toujours ?</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Oui, parfait.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Merci, rendez-vous confirmé — synthèse transmise à votre conseiller ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"HW Voice Caller\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Voix multilingues naturelles</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Qualification en 6 questions max</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Détection d\'intention vocale</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Synthèse post-appel structurée</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Interception des spams vocaux</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Mode outbound programmable</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Immobilier</strong>Qualification téléphonique des prospects avant transmission à l\'équipe commerciale terrain.</li>\n        <li><strong>Santé</strong>Confirmation systématique des rendez-vous patients pour réduire les créneaux perdus.</li>\n        <li><strong>Finance</strong>Recouvrement amiable structuré avec un ton respectueux et une trace complète de chaque échange.</li>\n        <li><strong>Call centers</strong>Pré-qualification des appels entrants avant transfert vers un conseiller humain disponible.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-check-circle\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de confirmation RDV</div>\n        <p class=\"aic-kpi-body\">Une reconfirmation systématique qui réduit sensiblement le taux de rendez-vous manqués.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-phone\"></i></div>\n        <div class=\"aic-kpi-ttl\">Volume d\'appels traités / jour</div>\n        <p class=\"aic-kpi-body\">Une capacité d\'appel constante, sans limite liée à la disponibilité d\'une équipe humaine.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-filter\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux de qualification</div>\n        <p class=\"aic-kpi-body\">Chaque appel aboutit à une donnée exploitable, transmise automatiquement au bon service.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. HW Voice Caller s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"HW Voice Caller\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#F22F46\"><i class=\"fal fa-sms\"></i>Twilio</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#00B388\"><i class=\"fal fa-phone-volume\"></i>Aircall</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#FF6600\"><i class=\"fal fa-phone\"></i>Zadarma</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#FF7A59\"><i class=\"fab fa-hubspot\"></i>HubSpot</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#00A1E0\"><i class=\"fab fa-salesforce\"></i>Salesforce</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#6264A7\"><i class=\"fab fa-microsoft\"></i>Teams Phone</div>\n        <div class=\"aic-orbit-item pos-7 rv\" style=\"--tool-color:#6B7280\"><i class=\"fal fa-network-wired\"></i>SIP Trunks</div>\n      </div>\n    </div>\n  </div>\n</section>','HW Voice Caller — Voicebot appels sortants | Hello World Agency','Agent vocal IA : voix multilingue FR/AR/EN, qualification en moins de 6 questions, transcription, synthèse post-appel, push CRM automatique.','fr'),(11,11,'Trading Signal Agent',NULL,'trading-signal-agent','Signaux Forex et Or automatisés','Des signaux Forex et Or générés par analyse technique continue, avec seuils configurables et alertes horodatées envoyées en temps réel.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Trading Signal Agent <em>— Signaux Forex et Or automatisés</em></h2>\n    <p class=\"aic-quote-src rv\">Des signaux Forex et Or générés par une analyse technique continue — directement sur votre canal préféré.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Surveiller le marché <em>24h/24</em><br>n\'est pas humain.</h2>\n        <p class=\"aic-lead rv\">Repérer manuellement chaque opportunité Forex ou Or demande une présence permanente devant les écrans, impossible à tenir dans la durée.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Surveillance manuelle épuisante</h3>\n            <p class=\"aic-pain-body\">Suivre les marchés Forex et Or en continu est incompatible avec une activité professionnelle normale.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Opportunités manquées la nuit</h3>\n            <p class=\"aic-pain-body\">Les mouvements de marché les plus intéressants surviennent souvent en dehors des heures de veille.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Analyse technique chronophage</h3>\n            <p class=\"aic-pain-body\">Calculer manuellement les indicateurs sur plusieurs paires à la fois ralentit chaque prise de décision.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Une analyse <em>continue</em>,<br>des signaux horodatés.</h2>\n        <p class=\"aic-lead rv\">Trading Signal Agent surveille en continu les paires Forex et l\'Or, calcule les indicateurs techniques configurés, et génère un signal horodaté dès qu\'un seuil pertinent est franchi, avec niveau d\'entrée, stop et objectif suggérés.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-coins\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Trading Signal Agent</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">AURUM</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Signal détecté sur XAU/USD — franchissement de résistance confirmé.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Donne-moi les niveaux.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Entrée 2 385, stop 2 372, objectif 2 410. Ratio risque/rendement favorable.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Merci, je consulte le journal.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Journal de performance mis à jour avec l\'historique complet des signaux ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Trading Signal Agent\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Analyse technique continue</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Seuils configurables</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Alertes horodatées</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Niveaux entrée / stop / objectif</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Journal de performance</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Push multicanal</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Traders indépendants</strong>Un copilote d\'analyse technique disponible en continu, sans mobiliser vos propres heures d\'écran.</li>\n        <li><strong>Gestionnaires patrimoniaux</strong>Un flux de signaux structuré pour alimenter une stratégie d\'allocation active et documentée.</li>\n        <li><strong>Formateurs trading</strong>Un support pédagogique concret pour illustrer l\'analyse technique en conditions réelles.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-chart-line\"></i></div>\n        <div class=\"aic-kpi-ttl\">Fiabilité des signaux émis</div>\n        <p class=\"aic-kpi-body\">Un suivi continu de la performance historique pour ajuster les seuils de déclenchement.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-stopwatch\"></i></div>\n        <div class=\"aic-kpi-ttl\">Délai de détection</div>\n        <p class=\"aic-kpi-body\">Un signal généré dès le franchissement du seuil technique configuré, sans latence humaine.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-book\"></i></div>\n        <div class=\"aic-kpi-ttl\">Historique consultable</div>\n        <p class=\"aic-kpi-body\">Chaque signal reste consultable pour analyser objectivement la performance dans le temps.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Trading Signal Agent s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Trading Signal Agent\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT4</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT5</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#2962FF\"><i class=\"fal fa-chart-area\"></i>TradingView</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#26A5E4\"><i class=\"fab fa-telegram\"></i>Telegram API</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#25D366\"><i class=\"fab fa-whatsapp\"></i>WhatsApp</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#6366F1\"><i class=\"fal fa-bell\"></i>Push mobile</div>\n      </div>\n    </div>\n  </div>\n</section>','Trading Signal Agent — Signaux Forex & Or IA | Hello World Agency','Agent IA de génération de signaux Forex et Or : analyse technique continue, seuils configurables, alertes horodatées et journal de performance.','fr'),(12,12,'Trade Executor',NULL,'trade-executor','Exécution automatique des signaux Telegram','Vos signaux Telegram exécutés automatiquement sur votre broker, sans délai ni ressaisie manuelle, avec une traçabilité complète de chaque ordre.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Trade Executor <em>— Exécution automatique des signaux Telegram</em></h2>\n    <p class=\"aic-quote-src rv\">Connectez votre canal Telegram à votre broker pour exécuter automatiquement vos signaux de trading Forex.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Un signal reçu, <em>un ordre</em><br>passé trop tard.</h2>\n        <p class=\"aic-lead rv\">Le temps de lire un signal Telegram et de le saisir manuellement sur votre plateforme, le marché a déjà bougé et le prix d\'entrée n\'est plus valide.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Délai de saisie manuelle</h3>\n            <p class=\"aic-pain-body\">Chaque seconde perdue entre la réception du signal et son exécution dégrade le prix d\'entrée réel.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Erreurs de saisie sous pression</h3>\n            <p class=\"aic-pain-body\">Saisir rapidement lot, stop et objectif dans l\'urgence augmente le risque d\'erreur humaine coûteuse.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Aucune traçabilité centralisée</h3>\n            <p class=\"aic-pain-body\">Sans journal automatique, difficile de savoir précisément quels signaux ont été exécutés et comment.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Du signal <em>à l\'ordre</em>,<br>sans intervention.</h2>\n        <p class=\"aic-lead rv\">Trade Executor lit vos canaux Telegram de signaux, en extrait automatiquement lot, entrée, stop et objectif, et transmet l\'ordre directement à votre broker via MT4 ou MT5, avec un journal complet de chaque exécution.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-bolt\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Trade Executor</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">VECTOR</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Signal détecté sur le canal « Gold Premium » : achat XAU/USD.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Exécute selon mes paramètres de risque.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Ordre passé : 0,5 lot, stop et objectif appliqués automatiquement.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Confirme l\'exécution.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Exécution confirmée en 0,8 seconde — journal mis à jour ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Trade Executor\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Lecture automatique des signaux</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Connexion broker directe</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Gestion du risque paramétrable</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Exécution en moins d\'une seconde</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Journal d\'exécution complet</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Filtrage des canaux sources</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Traders actifs</strong>Une exécution instantanée qui élimine le délai de saisie manuelle sur chaque signal reçu.</li>\n        <li><strong>Communautés de signaux</strong>Un service d\'exécution automatique proposé en complément aux membres de la communauté.</li>\n        <li><strong>Gestionnaires multi-comptes</strong>Réplication cohérente d\'une même stratégie de signaux sur plusieurs comptes de trading.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-val\">&lt;1<span>s</span></div>\n        <div class=\"aic-kpi-ttl\">Délai d\'exécution</div>\n        <p class=\"aic-kpi-body\">Un temps de réaction constant, indépendant de la disponibilité humaine devant l\'écran.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-check-circle\"></i></div>\n        <div class=\"aic-kpi-ttl\">Précision d\'exécution</div>\n        <p class=\"aic-kpi-body\">Les paramètres extraits du signal sont appliqués fidèlement, sans erreur de saisie.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-file-alt\"></i></div>\n        <div class=\"aic-kpi-ttl\">Traçabilité complète</div>\n        <p class=\"aic-kpi-body\">Chaque ordre exécuté reste consultable avec l\'intégralité de son contexte d\'origine.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Trade Executor s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Trade Executor\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#26A5E4\"><i class=\"fab fa-telegram\"></i>Telegram API</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT4</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT5</div>\n      </div>\n    </div>\n  </div>\n</section>','Trade Executor — Exécution automatique de signaux IA | Hello World Agency','Agent IA d\'exécution : connecte vos canaux Telegram de signaux directement à votre broker pour une exécution Forex automatique et tracée.','fr'),(13,13,'Market Alert Agent',NULL,'market-alert-agent','Alertes news et sentiment Forex sur Telegram','Tous vos signaux Telegram Forex et Or centralisés, filtrés et livrés sur votre téléphone — sans le bruit des faux signaux et des doublons.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Market Alert Agent <em>— Alertes news et sentiment Forex sur Telegram</em></h2>\n    <p class=\"aic-quote-src rv\">Tous vos signaux Telegram Forex/Or centralisés, filtrés et livrés à votre téléphone — sans le bruit.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">15 canaux Telegram,<br><em>80% de faux signaux.</em></h2>\n        <p class=\"aic-lead rv\">Vous êtes abonné à 15 canaux. 80% des signaux sont des fakes. Les faux trades plombent votre compte de trading.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Trop de canaux à surveiller</h3>\n            <p class=\"aic-pain-body\">Suivre quinze groupes Telegram simultanément rend impossible toute réaction rapide et cohérente.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Majorité de signaux non fiables</h3>\n            <p class=\"aic-pain-body\">La plupart des alertes reçues ne reposent sur aucune analyse technique sérieuse et faussent le jugement.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Faux trades qui plombent le compte</h3>\n            <p class=\"aic-pain-body\">Chaque signal suivi à tort représente une perte évitable qui aurait pu être filtrée en amont.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Un filtre IA <em>entre vous</em><br>et le bruit du marché.</h2>\n        <p class=\"aic-lead rv\">Market Alert Agent agrège les signaux de multiples canaux Telegram, les filtre, les analyse techniquement (RSI, MACD, supports), les note en fiabilité et ne livre que les alertes réellement actionnables.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-chart-line\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Market Alert Agent</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">SENTRA</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Nouveau signal EUR/USD détecté sur 4 canaux simultanément.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Il est fiable ?</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Analyse RSI/MACD confirmée, score de fiabilité 91/100. Signal validé.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Envoie-le-moi.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Alerte poussée sur votre app mobile et Telegram privé ✓</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Market Alert Agent\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Agrégation multi-canaux</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">Filtrage anti-fake-news</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Analyse technique intégrée</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">Scoring de fiabilité 0-100</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Push multicanal</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Journal de performance</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>Traders retail</strong>Un flux d\'alertes filtrées pour trader avec plus de sérénité, sans surcharge informationnelle.</li>\n        <li><strong>Family offices</strong>Un support d\'aide à la décision structuré pour les gestions patrimoniales actives sur le Forex.</li>\n        <li><strong>Écoles de trading</strong>Un outil pédagogique pour illustrer concrètement l\'analyse technique auprès des apprenants.</li>\n        <li><strong>Communautés Telegram</strong>Une valeur ajoutée directe pour les communautés monétisées autour du trading Forex et Or.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-check-double\"></i></div>\n        <div class=\"aic-kpi-ttl\">Fiabilité des alertes</div>\n        <p class=\"aic-kpi-body\">Seuls les signaux validés par recoupement et analyse technique sont réellement transmis.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-chart-line\"></i></div>\n        <div class=\"aic-kpi-ttl\">Performance moyenne des trades</div>\n        <p class=\"aic-kpi-body\">Un suivi continu de la qualité des signaux livrés pour ajuster les critères de filtrage.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-shield-alt\"></i></div>\n        <div class=\"aic-kpi-ttl\">Anti-fake-news</div>\n        <p class=\"aic-kpi-body\">Un filtrage systématique qui écarte les signaux non corroborés avant toute diffusion.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Market Alert Agent s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Market Alert Agent\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#26A5E4\"><i class=\"fab fa-telegram\"></i>Telegram API</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#5865F2\"><i class=\"fab fa-discord\"></i>Discord</div>\n        <div class=\"aic-orbit-item pos-3 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT4</div>\n        <div class=\"aic-orbit-item pos-4 rv\" style=\"--tool-color:#1F5C99\"><i class=\"fal fa-chart-line\"></i>MT5</div>\n        <div class=\"aic-orbit-item pos-5 rv\" style=\"--tool-color:#2962FF\"><i class=\"fal fa-chart-area\"></i>TradingView</div>\n        <div class=\"aic-orbit-item pos-6 rv\" style=\"--tool-color:#6366F1\"><i class=\"fal fa-bell\"></i>Push mobile</div>\n      </div>\n    </div>\n  </div>\n</section>','Market Alert Agent — Signaux trading IA | Hello World Agency','Agent IA signaux Forex/Or : agrégation multi-canaux Telegram, analyse RSI/MACD, scoring de fiabilité, push app mobile et anti-fake-news.','fr'),(14,14,'Expense Tracker',NULL,'expense-tracker','Suivi intelligent des dépenses et reçus','Vos notes de frais automatisées : photo, OCR, TVA marocaine détectée et export comptable en un clic, avec archivage légal sur dix ans.','<!-- ── ACCROCHE ── -->\n<div class=\"aic-accroche rv\">\n  <div class=\"aic-accroche-inner\">\n    <h2 class=\"aic-quote rv\">Expense Tracker <em>— Suivi intelligent des dépenses et reçus</em></h2>\n    <p class=\"aic-quote-src rv\">Notes de frais automatisées : photo, OCR, TVA marocaine et export comptable en un clic.</p>\n  </div>\n</div>\n\n<!-- ── PROBLÈME ── -->\n<section class=\"aic-section aic-problem\">\n  <div class=\"aic-container\">\n    <div class=\"aic-problem-inner\">\n      <div class=\"aic-problem-left\">\n        <div class=\"aic-eyebrow rv\">Le défi</div>\n        <h2 class=\"aic-h2 rv\">Un ticket perdu,<br><em>une TVA mal appliquée.</em></h2>\n        <p class=\"aic-lead rv\">Les tickets sont perdus, la TVA mal appliquée, l\'export comptable prend deux jours chaque fin de mois.</p>\n      </div>\n      <div class=\"aic-pain-stack\">\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">01</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Tickets papier égarés</h3>\n            <p class=\"aic-pain-body\">Sans capture immédiate, une part significative des justificatifs de dépense finit par se perdre.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">02</div>\n          <div>\n            <h3 class=\"aic-pain-title\">TVA appliquée manuellement</h3>\n            <p class=\"aic-pain-body\">Le calcul et la vérification manuelle de la TVA marocaine sur chaque reçu génèrent des erreurs récurrentes.</p>\n          </div>\n        </div>\n        <div class=\"aic-pain rv\">\n          <div class=\"aic-pain-num\">03</div>\n          <div>\n            <h3 class=\"aic-pain-title\">Export comptable en fin de mois</h3>\n            <p class=\"aic-pain-body\">La compilation manuelle vers le logiciel comptable mobilise deux jours complets chaque mois.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── PRÉSENTATION ── -->\n<section class=\"aic-section aic-off aic-pres\">\n  <div class=\"aic-container\">\n    <div class=\"aic-pres-inner\">\n      <div class=\"aic-pres-left\">\n        <div class=\"aic-eyebrow rv\">La solution</div>\n        <h2 class=\"aic-h2 rv\">Une photo, <em>un frais</em><br>traité et archivé.</h2>\n        <p class=\"aic-lead rv\">Expense Tracker capture la photo du reçu, en extrait TTC, TVA, date et fournisseur, catégorise selon le plan comptable marocain, détecte doublons et anomalies, et exporte vers Sage, QuickBooks ou Odoo.</p>\n        </div>\n      <div class=\"aic-pres-right rv\">\n        <div class=\"aic-chat\">\n          <div class=\"aic-chat-hdr\">\n            <div class=\"aic-chat-ava\"><i class=\"fal fa-receipt\"></i></div>\n            <div>\n              <div class=\"aic-chat-name\">Expense Tracker</div>\n              <div class=\"aic-chat-status\"><span class=\"aic-dot\"></span> En ligne maintenant</div>\n            </div>\n            <div class=\"aic-chat-badge\">LEDGER</div>\n          </div>\n          <div class=\"aic-chat-body\">\n            <div class=\"aic-msg aic-msg-bot\"><span>Reçu reçu ! Restaurant, 340 MAD TTC, TVA 20% détectée.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Catégorise en frais de représentation.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Catégorisé et archivé. Aucune anomalie ni doublon détecté.</span></div>\n            <div class=\"aic-msg aic-msg-user\"><span>Exporte vers Sage.</span></div>\n            <div class=\"aic-msg aic-msg-bot\"><span>Export Sage généré ✓ — prêt pour votre clôture mensuelle.</span></div>\n          </div>\n          <div class=\"aic-chat-inp\">\n            <span>Votre message...</span>\n            <button aria-label=\"Envoyer\"><i class=\"fal fa-paper-plane\"></i></button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── CAPACITÉS + PHOTO + CAS D\'USAGE ── -->\n<section class=\"aic-section aic-split\">\n  <div class=\"aic-split-bg\">\n    <img class=\"aic-split-bg-img\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"Expense Tracker\" loading=\"lazy\">\n    <img class=\"aic-split-bg-img aic-split-bg-blur\" src=\"{{FULL_BODY_PHOTO}}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\">\n  </div>\n  <div class=\"aic-container aic-split-inner\">\n    <div class=\"aic-split-col rv\">\n      <div class=\"aic-split-eyebrow\">Capacités clés</div>\n      <ol class=\"aic-split-list\">\n        <li>\n          <span class=\"aic-split-num\">1</span>\n          <span class=\"aic-split-list-text\">Capture photo mobile</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">2</span>\n          <span class=\"aic-split-list-text\">OCR haute précision</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">3</span>\n          <span class=\"aic-split-list-text\">Catégorisation plan comptable</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">4</span>\n          <span class=\"aic-split-list-text\">TVA marocaine auto-détectée</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">5</span>\n          <span class=\"aic-split-list-text\">Détection doublons et anomalies</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">6</span>\n          <span class=\"aic-split-list-text\">Export Sage · QuickBooks · Odoo</span>\n        </li>\n        <li>\n          <span class=\"aic-split-num\">7</span>\n          <span class=\"aic-split-list-text\">Archivage légal 10 ans</span>\n        </li>\n      </ol>\n    </div>\n    <div class=\"aic-split-col aic-split-col-right rv\">\n      <div class=\"aic-split-eyebrow\">Cas d\'usage sectoriels</div>\n      <ul class=\"aic-split-bullets\">\n        <li><strong>PME & Grands comptes</strong>Traitement centralisé des notes de frais de l\'ensemble des collaborateurs en déplacement.</li>\n        <li><strong>Cabinets comptables</strong>Automatisation de la collecte et de la catégorisation des justificatifs pour plusieurs clients.</li>\n        <li><strong>Agences de voyage</strong>Suivi précis des frais de mission et de déplacement pour chaque dossier client.</li>\n        <li><strong>Associations & ONG</strong>Traçabilité rigoureuse des dépenses pour répondre aux exigences de reporting des bailleurs.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ── KPI ── -->\n<section class=\"aic-section aic-kpi-sec\">\n  <div class=\"aic-container\">\n    <div class=\"aic-eyebrow rv\">Promesses chiffrées</div>\n    <h2 class=\"aic-h2 rv\">Des résultats <em>mesurables</em></h2>\n    <div class=\"aic-kpi-grid\">\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-clock\"></i></div>\n        <div class=\"aic-kpi-ttl\">Temps de traitement par reçu</div>\n        <p class=\"aic-kpi-body\">Un traitement quasi instantané depuis la photo jusqu\'à l\'archivage comptable final.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-balance-scale\"></i></div>\n        <div class=\"aic-kpi-ttl\">Conformité fiscale Maroc</div>\n        <p class=\"aic-kpi-body\">Une application systématique des règles de TVA en vigueur sur chaque type de dépense.</p>\n      </div>\n      <div class=\"aic-kpi-item rv\">\n        <div class=\"aic-kpi-ico\"><i class=\"fal fa-bullseye\"></i></div>\n        <div class=\"aic-kpi-ttl\">Taux d\'erreur OCR</div>\n        <p class=\"aic-kpi-body\">Une extraction fiable des montants et dates, avec validation humaine possible en cas de doute.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ── INTÉGRATIONS ── -->\n<section class=\"aic-section aic-orbit\">\n  <div class=\"aic-container\">\n    <div class=\"aic-orbit-inner\">\n      <div class=\"aic-orbit-left\">\n        <div class=\"aic-eyebrow rv\">Intégrations natives</div>\n        <div class=\"aic-orbit-heading\">\n          <h2 class=\"aic-h2 rv\">Se connecte à <em>votre stack</em> existant</h2>\n          <p class=\"aic-lead rv\">Un déploiement sans rupture dans votre infrastructure. Expense Tracker s\'intègre nativement avec les outils que vous utilisez déjà.</p>\n        </div>\n      </div>\n      <div class=\"aic-orbit-wrap\">\n        <div class=\"aic-orbit-ring-wrap r1\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r2\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-ring-wrap r3\"><div class=\"aic-orbit-ring\"></div><span class=\"aic-orbit-dot\"></span></div>\n        <div class=\"aic-orbit-center-halo\"></div>\n        <div class=\"aic-orbit-center rv\">\n          <img src=\"{{MAIN_PHOTO}}\" alt=\"Expense Tracker\" loading=\"lazy\">\n        </div>\n        <div class=\"aic-orbit-item pos-1 rv\" style=\"--tool-color:#00D639\"><i class=\"fal fa-calculator\"></i>Sage</div>\n        <div class=\"aic-orbit-item pos-2 rv\" style=\"--tool-color:#2CA